CREATE TABLE `customer_installation_details` (`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL,`installation_job_id` integer NOT NULL,`team_display_name` text DEFAULT '' NOT NULL,`show_team` integer DEFAULT false NOT NULL,`preparation_notes` text DEFAULT '' NOT NULL,`access_instructions` text DEFAULT '' NOT NULL,`checklist_json` text DEFAULT '[]' NOT NULL,`show_balance_reminder` integer DEFAULT false NOT NULL,`updated_by` integer NOT NULL,`updated_at` text DEFAULT CURRENT_TIMESTAMP NOT NULL); CREATE UNIQUE INDEX `customer_installation_details_installation_job_id_unique` ON `customer_installation_details` (`installation_job_id`); CREATE INDEX `customer_installation_details_job_idx` ON `customer_installation_details` (`installation_job_id`);
CREATE TABLE `installation_reschedule_requests` (`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL,`installation_job_id` integer NOT NULL,`user_id` integer NOT NULL,`requested_start` text,`requested_end` text,`request_contact` integer DEFAULT false NOT NULL,`reason` text DEFAULT '' NOT NULL,`status` text DEFAULT 'pending' NOT NULL,`idempotency_key` text NOT NULL,`created_at` text DEFAULT CURRENT_TIMESTAMP NOT NULL,`resolved_at` text); CREATE UNIQUE INDEX `installation_reschedule_requests_idempotency_key_unique` ON `installation_reschedule_requests` (`idempotency_key`); CREATE INDEX `installation_reschedule_requests_job_idx` ON `installation_reschedule_requests` (`installation_job_id`,`status`);
CREATE TABLE `installation_completion_records` (`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL,`installation_job_id` integer NOT NULL,`completed_items_json` text NOT NULL,`photo_urls_json` text DEFAULT '[]' NOT NULL,`exceptions_json` text DEFAULT '[]' NOT NULL,`published_by` integer NOT NULL,`published_at` text NOT NULL); CREATE UNIQUE INDEX `installation_completion_records_installation_job_id_unique` ON `installation_completion_records` (`installation_job_id`); CREATE INDEX `installation_completion_records_job_idx` ON `installation_completion_records` (`installation_job_id`);
CREATE TABLE `installation_completion_signatures` (`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL,`completion_record_id` integer NOT NULL,`user_id` integer NOT NULL,`printed_name` text NOT NULL,`signature_text` text NOT NULL,`evidence_sha256` text NOT NULL,`idempotency_key` text NOT NULL,`signed_at` text NOT NULL); CREATE UNIQUE INDEX `installation_completion_signatures_completion_record_id_unique` ON `installation_completion_signatures` (`completion_record_id`); CREATE UNIQUE INDEX `installation_completion_signatures_evidence_sha256_unique` ON `installation_completion_signatures` (`evidence_sha256`); CREATE UNIQUE INDEX `installation_completion_signatures_idempotency_key_unique` ON `installation_completion_signatures` (`idempotency_key`);
CREATE TABLE `installation_service_requests` (`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL,`installation_job_id` integer NOT NULL,`user_id` integer NOT NULL,`room_code` text NOT NULL,`window_code` text NOT NULL,`description` text NOT NULL,`photo_urls_json` text DEFAULT '[]' NOT NULL,`status` text DEFAULT 'open' NOT NULL,`idempotency_key` text NOT NULL,`created_at` text DEFAULT CURRENT_TIMESTAMP NOT NULL); CREATE UNIQUE INDEX `installation_service_requests_idempotency_key_unique` ON `installation_service_requests` (`idempotency_key`); CREATE INDEX `installation_service_requests_job_idx` ON `installation_service_requests` (`installation_job_id`,`status`);
